/// Send `amount` eth to `address` in the nitro-tesnode.
///
/// # Errors
///
/// May fail if unable to find the path to the node or if funding the newly
/// created account fails.
pub fn fund_account(address: Address, amount: u32) -> eyre::Result<()> {
    let node_script = get_node_path()?.join("test-node.bash");
    if !node_script.exists() {
        bail!("Test nitro node wasn't setup properly. Try to setup it first with `./scripts/nitro-testnode.sh -i -d`")
    }

    let output = std::process::Command::new(node_script)
        .arg("script")
        .arg("send-l2")
        .arg("--to")
        .arg(format!("address_{address}"))
        .arg("--ethamount")
        .arg(amount.to_string())
        .output()?;

    if !output.status.success() {
        let err = String::from_utf8_lossy(&output.stderr);
        bail!("account's wallet wasn't funded - address is {address}:\n{err}")
    }

    Ok(())
}
use std::{path::PathBuf, process::Command};

use eyre::Context;

/// Gets expected path to the nitro test node.
pub(crate) fn get_node_path() -> eyre::Result<PathBuf> {
    let manifest_dir = get_workspace_root()?;
    Ok(manifest_dir.join("nitro-testnode"))
}

/// Runs the following command to get the worskpace root:
///
/// ```bash
/// git rev-parse --show-toplevel
/// ```
pub(crate) fn get_workspace_root() -> eyre::Result<PathBuf> {
    let output = Command::new("git")
        .arg("rev-parse")
        .arg("--show-toplevel")
        .output()
        .wrap_err("should run `git rev-parse --show-toplevel`")?;

    let path = String::from_utf8_lossy(&output.stdout)
        .trim()
        .to_string()
        .parse::<PathBuf>()
        .wrap_err("failed to parse manifest dir path")?;
    Ok(path)
}

