1717	            contract_addr,
1718	            assets_to_deposit
1719	        ))?;
1720	        watch!(contract.mint(shares_to_mint, alice.address()))?;
1721	
1722	        let alice_balance = asset.balanceOf(alice.address()).call().await?._0;
1723	        let bob_balance = asset.balanceOf(bob.address()).call().await?._0;
1724	        assert_eq!(U256::ZERO, alice_balance);
